def esc(v): return html.escape(str(v),quote=True)
def rgb(c):
 c=c.lstrip('#');c=''.join(x*2 for x in c) if len(c)==3 else c
 return tuple(int(c[i:i+2],16) for i in (0,2,4))
def hx(v): return '#'+''.join(f'{max(0,min(255,round(x))):02x}' for x in v)
def mix(a,b,t):
 aa,bb=rgb(a),rgb(b);return hx(tuple(aa[i]*(1-t)+bb[i]*t for i in range(3)))
def lum(c):
 v=[]
 for x in rgb(c):
  x=x/255;v.append(x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4)
 return .2126*v[0]+.7152*v[1]+.0722*v[2]
def contrast(a,b):
 x,y=sorted((lum(a),lum(b)),reverse=True);return (x+.05)/(y+.05)
def readable(bg,c,minimum=4.5):
 if contrast(bg,c)>=minimum:return c
 return '#ffffff' if contrast(bg,'#ffffff')>=contrast(bg,'#111111') else '#111111'
def alpha(c,a):return c+f'{a:02x}'
def load_configs():
 data=[]
 for p in sorted(BUILD.glob('group-*.json')):data.extend(json.loads(p.read_text(encoding='utf-8')))
 by={c['slug']:c for c in data};actual={p.parent.name for p in ROOT.glob('design-md/*/DESIGN.md')}
 if set(by)!=actual:raise SystemExit(f'Missing={sorted(actual-set(by))};extra={sorted(set(by)-actual)};count={len(by)}')
 return [by[s] for s in sorted(actual)]
