def hero(c):
 x=[];layout=c['layout']
 if layout=='terminal':x.append('''<div class="terminal-card"><div class="terminal-bar"><i></i><i></i><i></i></div><div class="terminal-body"><div><span class="prompt">$</span> neosporin --info</div><div>status : <strong>OTC / EXTERNAL USE</strong></div><div>formula : <strong>3 antibacterial + 1 analgesic</strong></div><div class="terminal-big">24h <span style="font-size:13px">protection</span></div><div>size : <strong>14.2 g / 0.5 oz</strong></div><div><span class="prompt">$</span> ready <span class="cursor"></span></div></div></div>''')
 if layout=='dashboard':x.append('''<div class="dash-card"><div class="dash-label">ANTIBACTERIAL PROTECTION</div><div class="dash-value">24 hours</div><svg class="sparkline" viewBox="0 0 270 70" preserveAspectRatio="none"><path d="M0 65L0 51L25 54L50 42L75 46L100 27L125 32L150 20L175 25L200 12L225 18L250 7L270 10L270 65Z"/><polyline points="0,51 25,54 50,42 75,46 100,27 125,32 150,20 175,25 200,12 225,18 250,7 270,10"/></svg><div class="dash-label">DAILY USE · 1–3× · 14.2 g</div></div>''')
 if layout in ('editorial','luxury'):x.append('<div class="giant-type">24</div>' if layout=='editorial' else '<div class="giant-type">N°</div>')
 if layout=='retro':x.append('<div class="sticker">NEW!</div>')
 if layout=='masonry':x.append('<div class="masonry-tiles"><i></i><i></i><i></i><i></i></div>')
 x.append(TUBE)
 if layout!='terminal':x.append('<div class="float-chip chip-time"><strong>24h</strong><span>抗菌防护</span></div><div class="float-chip chip-size"><strong>14.2g</strong><span>0.5 oz · 随身装</span></div>')
 return '\n'.join(x)
