def deck(c):
 bg=c['bg'].lower();surface=c['surface'].lower();text=readable(bg,c['text'].lower());muted=readable(bg,c['muted'].lower(),3.1);accent=c['accent'].lower();accent2=c['accent2'].lower();safe=accent
 if contrast(bg,safe)<2.2:safe=accent2 if contrast(bg,accent2)>contrast(bg,accent) else text
 on=readable(safe,c['onAccent'].lower());line=c['line'].lower()
 if contrast(bg,line)<1.12:line=mix(bg,text,.2)
 cb,cs,ct,cm,cl=bg,surface,text,muted,line
 if c.get('lightContent') and lum(bg)<.38 and lum(surface)>.48:cb,ct,cs,cm,cl=surface,bg,mix(surface,bg,.045),mix(surface,bg,.67),mix(surface,bg,.16)
 def reading_color(base):
  if contrast(cb,base)>=3:return base
  for step in range(1,10):
   candidate=mix(base,ct,step/10)
   if contrast(cb,candidate)>=3:return candidate
  return ct
 ra,ra2=reading_color(safe),reading_color(accent2)
 v=dict(c);v.update({'name':esc(c['name']),'summary':esc(c['summary']),'slug':esc(c['slug']),'specPath':esc('design-md/'+c['slug']+'/DESIGN.md'),'heroVisual':hero(c),'bg':bg,'surface':surface,'text':text,'muted':muted,'accentSafe':safe,'accent2':accent2,'onAccent':on,'line':line,'contentBg':cb,'contentSurface':cs,'contentText':ct,'contentMuted':cm,'contentLine':cl,'accentSoft':alpha(safe,38),'accentFaint':alpha(safe,20),'accent2Soft':alpha(accent2,32),'readingAccent':ra,'readingAccent2':ra2,'readingAccentSoft':alpha(ra,38),'readingAccentFaint':alpha(ra,20),'readingAccent2Soft':alpha(ra2,32)})
 return '<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Cache-Control" content="no-store"><title>NEOSPORIN® · '+esc(c['name'])+' 风格幻灯片</title><style>'+Template(CSS).substitute(v)+'</style><script>document.documentElement.classList.add("js")</script></head><body>'+Template(BODY).substitute(v)+'</body></html>'
def index(configs):
 filters=''.join(f'<button class="filter" data-filter="{esc(cat)}">{esc(cat)}</button>' for cat,_ in CATEGORY_GROUPS);cards=[]
 for i,c in enumerate(configs,1):
  search=' '.join([c['name'],c['slug'],c['summary'],CATEGORIES[c['slug']],LAYOUT_ZH[c['layout']],EFFECT_ZH[c['effect']]]).lower();sw=''.join(f'<i style="background:{esc(c[k])}"></i>' for k in ('bg','accent','accent2','surface'))
  cards.append(f'''<article class="card" data-category="{esc(CATEGORIES[c['slug']])}" data-search="{esc(search)}"><a class="preview-link" href="{esc(c['slug'])}.html"><div class="preview" style="--card-bg:{esc(c['bg'])};--card-text:{esc(c['text'])}"><span class="preview-fallback">{esc(c['name'])}</span><img src="_previews/{esc(c['slug'])}.png" alt="{esc(c['name'])} 风格幻灯片封面预览" loading="lazy" onerror="this.remove()"><span class="open-badge">打开 4 页示例 ↗</span></div></a><div class="card-info"><div class="card-top"><span class="number">{i:02d}</span><h2>{esc(c['name'])}</h2><span class="category">{esc(CATEGORIES[c['slug']])}</span></div><p class="summary">{esc(c['summary'])}</p><div class="card-meta"><span class="swatches">{sw}</span><span class="tags">{esc(LAYOUT_ZH[c['layout']])} · {esc(EFFECT_ZH[c['effect']])}</span><a class="spec-link" href="../../design-md/{esc(c['slug'])}/DESIGN.md">规范 ↗</a></div></div></article>''')
 body=Template(INDEX_BODY).substitute(filterButtons=filters,cards='\n'.join(cards));return '<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Cache-Control" content="no-store"><title>84 种风格 · NEOSPORIN 幻灯片图鉴</title><style>'+INDEX_CSS+'</style></head><body>'+body+'</body></html>'
def main():
 configs=load_configs()
 for c in configs:(OUT/(c['slug']+'.html')).write_text(deck(c),encoding='utf-8')
